script:
"=== extracting Zen token ==="
$authPath = "$env:USERPROFILE\.local\share\opencode\auth.json"
if (Test-Path $authPath) {
  $auth = Get-Content $authPath | ConvertFrom-Json
  $token = $auth.opencode.key
  "Token found, length: $($token.Length)"
  # Store token in a temp file for next step (not in output)
  $token | Out-File -FilePath "$env:TEMP\zen_token.txt" -Encoding utf8 -NoNewline
  "Token saved to temp file"
} else {
  "Auth file not found at $authPath"
}
